from dtkcore import d_real, d_inliststring

import gnomon.core

from gnomon.utils import algorithmPlugin
from gnomon.utils.decorators import imageInput, imageOutput
# #}
# add your imports before the next gnomon tag

import numpy as np
from skimage.feature import hessian_matrix, hessian_matrix_eigvals
from timagetk import SpatialImage, MultiChannelImage


# {# gnomon, plugin.class

@algorithmPlugin(version='0.1.0', coreversion='0.81.0')
@imageInput(attr='img', data_plugin='gnomonImageDataMultiChannelImage')
@imageOutput(attr='filtered_img', data_plugin='gnomonImageDataMultiChannelImage')
class hessianEigenvalueImageFilter(gnomon.core.gnomonAbstractFormAlgorithm):
    """
    Implements a Hessian eigenvalue filter.
    """

    def __init__(self):
        super().__init__()

        self._parameters = {}
        self._parameters['sigma'] = d_real('Sigma', 0.2, 0., 3., 2, 'Sigma for the Hessian matrix computation (in µm)')
        self._parameters['filter_type'] = d_inliststring('Filter type', "none", ["hill", "exp", "none"], 'Type of filter function applied to the eigenvalues')
        self._parameters['gamma'] = d_real('Gamma', 1., 0., 1., 2, 'Enhancement factor used in the filter function')
        self._parameters['channel_name'] = d_inliststring('Channel', '', [''], 'Channel to process')

        self.img = {}
        self.filtered_img = {}

    def run(self):
        self.filtered_img = {}
        for time in self.img.keys():
            img = self.img[time]
            # #}
            # implement the run method

            channel_name = self['channel_name'] if 'channel_name' in self._parameters.keys() else img.channel_names[0]
            img = img.get_channel(channel_name)

            hess = hessian_matrix(img, sigma=self['sigma']/np.array(img.voxelsize))
            hess_evals = hessian_matrix_eigvals(hess)

            last_hess_evals = np.abs(np.minimum(0, hess_evals[2]))

            if self['filter_type'] == 'hill':
                hess_img = 1./(1 + np.power(last_hess_evals/self['gamma'], 2))
            elif self['filter_type'] == 'exp':
                hess_img = np.exp(-np.power(last_hess_evals/self['gamma'], 2))
            else:
                hess_img = -last_hess_evals

            max_intensity = 255 if img.dtype == np.uint8 else 65535

            hess_img = max_intensity * (np.nanmax(hess_img) - hess_img)/(np.nanmax(hess_img) - np.nanmin(hess_img))
            hess_img = SpatialImage(hess_img.astype(img.dtype),
                                    voxelsize=img.voxelsize)

            self.filtered_img[time] = MultiChannelImage({'': hess_img})

    def refreshParameters(self):
        if len(self.img) > 0:
            img = list(self.img.values())[0]
            if len(img.channel_names) == 1:
                if 'channel_name' in self._parameters.keys():
                    del self._parameters['channel_name']
            else:
                if 'channel_name' not in self._parameters.keys():
                    self._parameters['channel_name'] = d_inliststring('Channel to process', '', [''])
                channel_name = self['channel_name']
                self._parameters['channel_name'].setValues(img.channel_names)

                if channel_name in img.channel_names:
                    self._parameters['channel_name'].setValue(channel_name)
                else:
                    self._parameters['channel_name'].setValue(img.channel_names[0])
